{
  "segment_function": "To define the concept of work (homo faber), distinguish it from labor, and elaborate on the durability, objectivity, and stability of the human artifice.",
  "claims": [
    {
      "claim": "Homo faber makes and works upon things, distinguishing this activity from animal laborans which labors and mixes with things.",
      "claim_type": "author_position",
      "supporting_excerpt": "The work of our hands, as distinguished from the labor of our bodies— homo faber who makes and literally “works upon” 1 as distinguished from the animal laborans which labors and “mixes with”—fabricates the sheer unending variety of things whose sum total constitutes the human artifice.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "Durability gives the things of the world relative independence and objectivity, allowing them to withstand the biological needs of their makers and stabilize human identity.",
      "claim_type": "author_position",
      "supporting_excerpt": "It is this durability which gives the things of the world their relative independence from men who produced and use them, their “objectivity” which makes them withstand, “stand against” 2 and endure, at least for a time, the voracious needs and wants of their living makers and users.",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "Human artifice",
      "definition": "The sum total of the sheer unending variety of things made and fabricated by homo faber that provide stability and solidity to house mortal humans."
    },
    {
      "term": "Durability",
      "definition": "The characteristic of world things that gives them relative independence from their producers and users, allowing them to endure against biological needs and wear out gradually through usage rather than through inherent destruction."
    }
  ],
  "distinctions": [
    {
      "item_a": "Homo faber",
      "item_b": "Animal laborans",
      "distinction": "Homo faber makes and works upon things to fabricate the human artifice, whereas animal laborans labors and mixes with things."
    },
    {
      "item_a": "Use",
      "item_b": "Consumption",
      "distinction": "Destruction is incidental and occurs gradually through wearing out in use, whereas destruction is inherent and the inevitable destiny of consumer goods."
    }
  ],
  "unresolved_context": []
}

